function cleanData(raw) {
  const report = { rawRows: raw.length, duplicatesRemoved: 0, invalidRowsDropped: 0, missingNumbersSetToZero: 0, datesStandardised: 'Order Date and Ship Date converted to YYYY-MM-DD' };
  const seen = new Set();
  const rows = [];
  for (const r of raw) {
    const o = {};
    for (const [k, v] of Object.entries(r)) o[str(k)] = typeof v === 'string' ? str(v).replace(/\s+/g, ' ') : v;
    const key = o['Row ID'] !== undefined && o['Row ID'] !== '' ? 'id:' + o['Row ID'] : JSON.stringify(o);
    if (seen.has(key)) { report.duplicatesRemoved++; continue; }
