  const metricsReq = (spec.metrics && spec.metrics.length ? [].concat(spec.metrics) : ['sales']).map(m => ({ raw: m, key: normMetric(m) }));
  const badMetric = metricsReq.find(m => !m.key);
  if (badMetric) return { ok: false, error: `Unknown metric "${badMetric.raw}".`, validMetrics: METRIC_LIST };
  const metricKeys = metricsReq.map(m => m.key);

  const dims = [];
  for (const g of [].concat(spec.groupBy || []).slice(0, 2)) {
    const col = resolve(g);
    if (!col) return { ok: false, error: `Unknown groupBy field "${g}".`, validFields };
    dims.push(col);
  }

  const total = newAcc();
  for (const r of data) addAcc(total, r);
  const totals = finishAcc(total, discScale);

  let groups = [];
  if (dims.length) {
    const map = new Map();
    for (const r of data) {
      const parts = dims.map(d => { const v = r[d]; return v === '' || v === null || v === undefined ? 'Unknown' : String(v); });
      const key = parts.join(' | ');
      if (!map.has(key)) map.set(key, { parts, sortParts: dims.map(d => d === 'Month' ? r._monthNum : r[d]), acc: newAcc() });
      addAcc(map.get(key).acc, r);
    }
    groups = [...map.entries()].map(([name, g]) => ({ name, parts: g.parts, _sort: g.sortParts, ...finishAcc(g.acc, discScale) }));

    for (const h of (spec.having || [])) {
      const mk = normMetric(h.metric);
      if (!mk) return { ok: false, error: `Unknown having metric "${h.metric}".`, validMetrics: METRIC_LIST };
      const op = norm(h.op), v = Number(h.value);
      groups = groups.filter(g => op === 'gt' ? g[mk] > v : op === 'gte' ? g[mk] >= v : op === 'lt' ? g[mk] < v : op === 'lte' ? g[mk] <= v : op === 'eq' ? g[mk] === v : true);
    }

    const timeFirst = TIME_DIMS.has(dims[0]);
    const sortKey = spec.sortBy ? normMetric(spec.sortBy) : null;
    if (spec.sortBy && !sortKey && !timeFirst) return { ok: false, error: `Unknown sortBy metric "${spec.sortBy}".`, validMetrics: METRIC_LIST };
    if (timeFirst && !sortKey) {
      const dir = norm(spec.order) === 'desc' ? -1 : 1;
      groups.sort((a, b) => {
        for (let i = 0; i < a._sort.length; i++) {
          if (a._sort[i] < b._sort[i]) return -1 * dir;
          if (a._sort[i] > b._sort[i]) return 1 * dir;
        }
        return 0;
      });
    } else {
      const k = sortKey || metricKeys[0];
      const dir = norm(spec.order) === 'asc' ? 1 : -1;
      groups.sort((a, b) => ((a[k] ?? 0) - (b[k] ?? 0)) * dir);
    }
  }

  const groupCount = groups.length;
  const defLimit = dims.length && TIME_DIMS.has(dims[0]) ? 60 : 25;
  const limit = Math.min(Number(spec.limit) || defLimit, 200);
  groups = groups.slice(0, limit);

  // Return only the requested metrics (plus the sort metric) to keep the LLM context small.
  const keep = new Set([...metricKeys, ...(spec.sortBy && normMetric(spec.sortBy) ? [normMetric(spec.sortBy)] : [])]);
  groups = groups.map(g => {
    const o = { name: g.name, parts: g.parts };
    for (const k of METRIC_LIST) if (keep.has(k)) o[k] = g[k];
    return o;
  });

  return {
    ok: true,
    filtersApplied: applied,
    rowsMatched: data.length,
    totals,
    groupBy: dims,
    groupCount,
    returned: groups.length,
    groups,
    warning: data.length === 0 ? 'No rows matched the filters. Check exact values in the dataset profile.' : undefined
  };
}

