rows.forEach((r, i) => {
  const key = JSON.stringify(Object.entries(r).filter(([k]) => !['rowid', 'rownumber'].includes(norm(k))));
  const line = col(r, 'orderid') + '|' + col(r, 'productid');
  if (seen.has(key)) add(i, 'Duplicate row', 'all columns', '', 'Identical to sheet row ' + seen.get(key));
  else if (!isBlank(col(r, 'orderid')) && seenLine.has(line))
    add(i, 'Possible duplicate', 'Order ID + Product ID', line, 'Same order and product as sheet row ' + seenLine.get(line));
  if (!seen.has(key)) seen.set(key, rowNo(i));
  if (!seenLine.has(line)) seenLine.set(line, rowNo(i));
});

// ---------- 3. Dates ----------
const mk = (y, mo, d) => { const dt = new Date(Date.UTC(y, mo - 1, d));
  return dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d ? dt : null; };
const toDate = v => {
  if (typeof v === 'number' && v > 20000 && v < 80000) return new Date(Date.UTC(1899, 11, 30) + v * 864e5);
  const s = String(v).trim(); let m;
  if ((m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/))) return mk(+m[1], +m[2], +m[3]);
  if ((m = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2,4})/))) return mk(m[3].length === 2 ? 2000 + +m[3] : +m[3], +m[1], +m[2]);
  return null;
};
const toISO = v => { const d = toDate(v); return d ? d.toISOString().slice(0, 10) : null; };
const fmtOf = v => { const s = String(v).trim();
  if (/^\d{4}-\d{1,2}-\d{1,2}/.test(s)) return 'YYYY-MM-DD';
  if (/^\d{1,2}-\d{1,2}-\d{2}$/.test(s)) return 'MM-DD-YY';
  if (/^\d{1,2}-\d{1,2}-\d{4}$/.test(s)) return 'MM-DD-YYYY';
  if (/^\d{1,2}\/\d{1,2}\/\d{2,4}$/.test(s)) return 'M/D/YYYY';
  return 'other'; };
const DATE_COLS = ['orderdate', 'shipdate'];
DATE_COLS.forEach(n => {
  const counts = {};
  rows.forEach(r => { if (!isBlank(col(r, n))) { const f = fmtOf(col(r, n)); counts[f] = (counts[f] || 0) + 1; } });
  const main = Object.keys(counts).sort((a, b) => counts[b] - counts[a])[0];
  rows.forEach((r, i) => { const v = col(r, n); if (isBlank(v)) return;
    const d = toDate(v);
    if (!d) add(i, 'Invalid date', keyOf(r, n), v, 'Cannot be read as a real date');
    else if (d.getUTCFullYear() < 2000 || d.getUTCFullYear() > new Date().getUTCFullYear() + 1)
      add(i, 'Date out of range', keyOf(r, n), v, 'Year ' + d.getUTCFullYear() + ' looks wrong');
    else if (FLAG_FORMAT_MIX && fmtOf(v) !== main) add(i, 'Inconsistent date format', keyOf(r, n), v, 'Most rows use ' + main); });
});
rows.forEach((r, i) => {
  const o = toDate(col(r, 'orderdate') ?? ''), s = toDate(col(r, 'shipdate') ?? '');
  if (o && s && s < o) add(i, 'Ship before order', 'Ship Date', col(r, 'shipdate'), 'Ship date is before order date');
  else if (o && s && (s - o) / 864e5 > 60)
    add(i, 'Long shipping gap', 'Ship Date', col(r, 'shipdate'), 'Ship date is ' + Math.round((s - o) / 864e5) + ' days after order date (day and month may be swapped)');
});

// ---------- 4. Impossible and absurd values (normal profits/losses are NOT flagged) ----------
const q = (arr, p) => { const a = [...arr].sort((x, y) => x - y), pos = (a.length - 1) * p, lo = Math.floor(pos);
  return a[lo] + (a[Math.ceil(pos)] - a[lo]) * (pos - lo); };
const num = (r, n) => { const v = col(r, n); return isBlank(v) || isNaN(Number(v)) ? null : Number(v); };

['sales', 'profit', 'quantity', 'discount'].forEach(n => {
  if (!rows.length || keyOf(rows[0], n) === undefined) return;
  rows.forEach((r, i) => { const v = col(r, n);
    if (!isBlank(v) && isNaN(Number(v))) add(i, 'Not a number', keyOf(r, n), v, 'Expected a numeric value'); });
});
rows.forEach((r, i) => {
  const s = num(r, 'sales'), p = num(r, 'profit'), qty = num(r, 'quantity'), d = num(r, 'discount');
  if (s !== null && s < 0) add(i, 'Impossible value', keyOf(r, 'sales'), s, 'Negative sales');
  if (qty !== null && qty <= 0) add(i, 'Impossible value', keyOf(r, 'quantity'), qty, 'Quantity must be above 0');
  if (d !== null && (d < 0 || d > 1)) add(i, 'Impossible value', keyOf(r, 'discount'), d, 'Discount must be between 0 and 1');
  if (s !== null && p !== null && s > 0) {
    if (p > s) add(i, 'Impossible value', keyOf(r, 'profit'), p, 'Profit is higher than sales');
    else if (QUARANTINE_OUTLIERS && p < MIN_MARGIN * s)
      add(i, 'Suspicious margin', keyOf(r, 'profit'), p, 'Loss is more than ' + Math.abs(MIN_MARGIN * 100) + '% of sales');
  }
});
// Extreme sales / quantity, measured on a log scale (money is skewed, so large values are normal)
if (QUARANTINE_OUTLIERS) ['sales', 'quantity'].forEach(n => {
  if (!rows.length || keyOf(rows[0], n) === undefined) return;
  const logs = rows.map(r => num(r, n)).filter(v => v !== null && v > 0).map(Math.log);
  if (logs.length < 20) return;
  const q1 = q(logs, .25), q3 = q(logs, .75), iqr = q3 - q1;
  const hi = Math.exp(q3 + OUTLIER_IQR * iqr), lo = Math.exp(q1 - OUTLIER_IQR * iqr);
  rows.forEach((r, i) => { const v = num(r, n); if (v === null || v <= 0) return;
    if (v > hi || v < lo) add(i, 'Outlier', keyOf(r, n), v, 'Extremely unusual for this column (normal range ' + lo.toFixed(2) + ' to ' + hi.toFixed(0) + ')'); });
});

// ---------- Output: one item per row ----------
return rows.map((r, i) => {
  const list = byRow[i];
  if (!list) {
    const clean = { ...r };                       // clean row: standardise the dates
    for (const k of Object.keys(clean)) {
      if (DATE_COLS.includes(norm(k))) clean[k] = toISO(clean[k]) ?? clean[k];
    }
    return { json: clean };
  }
  return { json: {                                // flagged row: keep original values
    'Issue Count': list.length,
    'Issue Types': [...new Set(list.map(x => x.type))].join(', '),
    'Issue Details': list.map(x => x.type + ' [' + x.column + ']: ' + x.detail + (x.value ? ' (value: ' + x.value + ')' : '')).join(' | '),
    ...r,
  } };
});
